def dichotomie(f, a, b, eps=1e-6, max_iter=60):
    """Retourne une approximation de la racine de f dans [a,b] par dichotomie."""
    if f(a)*f(b) > 0:
        raise ValueError("Pas de changement de signe")
    for _ in range(max_iter):
        m = (a + b) / 2
        if b - a < 2*eps or abs(f(m)) < 1e-12:
            return m
        if f(a)*f(m) <= 0:
            b = m
        else:
            a = m
    return (a + b) / 2
